#[test]
fn test_array_agg_row_constructor_is_rejected() {
    // From: testing_data/aggregates/nested_json/09_array_agg_row_constructor_is_rejected.json
    // "array_agg of a multi-field ROW() constructor must not silently collapse to the first field's type -- it has no single neutral type today, so it is rejected with an actionable error instead of reaching codegen as an unresolved element type (#223)"
    let schema_sql = &["CREATE TABLE orders (id SERIAL PRIMARY KEY, total NUMERIC NOT NULL);"];

    let query_sql =
        "-- @name GetOrderRows\n-- @returns :one\nSELECT array_agg(ROW(o.id, o.total)) AS rows FROM orders o;";

    let catalog_result = scythe_core::catalog::Catalog::from_ddl(schema_sql);
    if let Ok(catalog) = catalog_result {
        let query_result = scythe_core::parser::parse_query(query_sql);
        if let Ok(query) = query_result {
            let result = scythe_core::analyzer::analyze(&catalog, &query);
            assert!(result.is_err(), "expected analysis to fail");
            let err = result.unwrap_err();
            let err_msg = err.to_string();
            assert!(
                err_msg.contains("UNRESOLVED_TYPE"),
                "error should contain code {:?}, got: {}",
                "UNRESOLVED_TYPE",
                err_msg
            );
            assert!(
                err_msg.contains("ROW(...)"),
                "error should contain {:?}, got: {}",
                "ROW(...)",
                err_msg
            );
        } else {
            // Parse failed -- that counts as expected failure.
            let err = query_result.unwrap_err();
            let err_msg = err.to_string();
            assert!(
                err_msg.contains("UNRESOLVED_TYPE"),
                "error should contain code {:?}, got: {}",
                "UNRESOLVED_TYPE",
                err_msg
            );
            assert!(
                err_msg.contains("ROW(...)"),
                "error should contain {:?}, got: {}",
                "ROW(...)",
                err_msg
            );
        }
    } else {
        // DDL processing failed -- that counts as expected failure.
        let err = catalog_result.unwrap_err();
        let err_msg = err.to_string();
        assert!(
            err_msg.contains("UNRESOLVED_TYPE"),
            "error should contain code {:?}, got: {}",
            "UNRESOLVED_TYPE",
            err_msg
        );
        assert!(
            err_msg.contains("ROW(...)"),
            "error should contain {:?}, got: {}",
            "ROW(...)",
            err_msg
        );
    }
}

